  background: #0f172a;
  color: #e2e8f0;
  display: flex;
  justify-content: center;
  padding: 48px 20px;
  font-family: var(--font-geist-sans, "Inter", system-ui);
}

.main {
  width: 100%;
  max-width: 820px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.card,
.statusCard {
  background: #111827;
  border: 1px solid #1f2937;
  border-radius: 16px;
  padding: 28px;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.35);
}

.card h1 {
  font-size: 28px;
  margin-bottom: 8px;
}

.subtitle {
  color: #94a3b8;
  margin-bottom: 24px;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.label {
  font-size: 14px;
  color: #cbd5f5;
}

input {
  border-radius: 12px;
  border: 1px solid #334155;
  background: #0f172a;
  padding: 12px 14px;
  color: #e2e8f0;
  font-size: 15px;
}

button {
  border-radius: 12px;
  border: none;
  background: #38bdf8;
  color: #0f172a;
  font-weight: 600;
  padding: 12px 16px;
  cursor: pointer;

