  max-width: 820px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.card,
.statusCard {
  background: #111827;
  border: 1px solid #1f2937;
  border-radius: 16px;
  padding: 28px;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.35);
}

.card h1 {
  font-size: 28px;
  margin-bottom: 8px;
}

.subtitle {
  color: #94a3b8;
  margin-bottom: 24px;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.label {
  font-size: 14px;
  color: #cbd5f5;
}

input {
  border-radius: 12px;
  border: 1px solid #334155;
  background: #0f172a;
  padding: 12px 14px;
  color: #e2e8f0;
  font-size: 15px;
}

button {
  border-radius: 12px;
  border: none;
  background: #38bdf8;
  color: #0f172a;
  font-weight: 600;
  padding: 12px 16px;
  cursor: pointer;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

button:not(:disabled):hover {
  transform: translateY(-1px);
}

.error {
  color: #fca5a5;
  margin-top: 12px;
}

.statusCard h2 {
  margin-bottom: 16px;
}

.statusRow {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid #1f2937;
}

.statusRow:last-of-type {
  border-bottom: none;
}

.statusLabel {
  color: #94a3b8;
  font-size: 14px;
}

.statusValue {
  font-family: "JetBrains Mono", "SFMono-Regular", monospace;
  font-size: 13px;
  word-break: break-all;
  text-align: right;
}

.verify {
  margin-top: 18px;
  width: 100%;
  background: #22c55e;
  color: #0f172a;
}

